import 'bootstrap/dist/css/bootstrap.min.css';
import './App.css';
import { useEffect, useState } from 'react';
import { Routes, Route, Link } from 'react-router-dom';

import Login from './pages/Login';
import Registro from './pages/Registro';
import Home from './pages/Home';
import Productos from './pages/Productos';
import Sale from './pages/Sale';
import Pedidos from './pages/Pedidos';
import Pago from './pages/Pago';
import AnadirProductos from './pages/Admin/AnadirProductos';
import CambiarContrasena from './pages/Cambiarcontrasena/cambiarcontrasena';
import PrivateRoute from './components/PrivateRoute';

export default function MyApp() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const actualizarUsuario = () => {
      const storedUser = localStorage.getItem('user');
      if (storedUser) {
        setUser(JSON.parse(storedUser));
      } else {
        setUser(null);
      }
    };

    actualizarUsuario();

    window.addEventListener("userChanged", actualizarUsuario);

    return () => {
      window.removeEventListener("userChanged", actualizarUsuario);
    };
  }, []);

  const logout = () => {
    localStorage.clear();
    setUser(null);
    window.dispatchEvent(new Event("userChanged"));
    window.location.href = '/';
  };

  return (
    <div>
      <nav className="navbar navbar-expand-lg cozy-navbar">
        <div className="container-fluid navbar-container">
          <Link to="/" className="navbar-brand cozy-brand">
            Cozy Home
          </Link>

          <div className="collapse navbar-collapse show">
            <div className="navbar-nav me-auto">
              <Link className="nav-link cozy-nav-link" to="/productos">
                Productos
              </Link>

              <Link className="nav-link cozy-nav-link" to="/sale">
                Compra
              </Link>

              <Link className="nav-link cozy-nav-link" to="/pedidos">
                Pedidos Realizados
              </Link>

              {user && (
                <Link className="nav-link cozy-nav-link" to="/cambiar-contrasena">
                  Cambiar contraseña
                </Link>
              )}
            </div>

            <div className="d-flex align-items-center gap-2">
              {!user && (
                <>
                  <Link to="/login">
                    <button className="btn cozy-btn-primary">
                      Log in
                    </button>
                  </Link>

                  <Link to="/registro">
                    <button className="btn cozy-btn-secondary">
                      Registrarse
                    </button>
                  </Link>
                </>
              )}

              {user && (
                <>
                  <span className="me-2">
                    Hola, <strong>{user.primer_Nombre}</strong>
                  </span>

                  <button
                    className="btn btn-outline-dark"
                    onClick={logout}
                  >
                    Cerrar sesión
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      </nav>

      <Routes>
        <Route path="/pago" element={<Pago />} />
        <Route path="/" element={<Home />} />
        <Route path="/productos" element={<Productos />} />
        <Route path="/login" element={<Login />} />
        <Route path="/registro" element={<Registro />} />
        <Route path="/cambiar-contrasena" element={<CambiarContrasena />} />

        <Route
          path="/sale"
          element={
            <PrivateRoute user={user}>
              <Sale />
            </PrivateRoute>
          }
        />

        <Route
          path="/pedidos"
          element={
            <PrivateRoute user={user}>
              <Pedidos />
            </PrivateRoute>
          }
        />

        <Route path="/admin" element={<AnadirProductos />} />
      </Routes>
    </div>
  );
}
